before.content:
const root = process.cwd();
const schema = JSON.parse(await readFile(path.join(root, "protocol/acp/v2-preview/schema.json"), "utf8"));
const fixtures = JSON.parse(await readFile(path.join(root, "protocol/acp/v2-preview/fixtures.json"), "utf8"));
const validate = new Ajv2020({ allErrors: true, strict: false, validateFormats: false }).compile(schema);
for (const [index, fixture] of fixtures.entries()) {
  if (!validate(fixture)) {
    throw new Error(`ACP v2 fixture ${index} is invalid: ${JSON.stringify(validate.errors)}`);
  }
}
process.stdout.write(`ACP v2 fixtures valid: ${fixtures.length}\n`);

after.content:
const root = process.cwd();
const schema = JSON.parse(await readFile(path.join(root, "protocol/acp/v2-preview/schema.json"), "utf8"));
const catalog = JSON.parse(await readFile(path.join(root, "protocol/acp/v2-preview/fixtures.json"), "utf8"));
if (catalog.schemaVersion !== "1.0" || !Array.isArray(catalog.fixtures)) {
  throw new Error("ACP v2 fixture catalog is invalid");
}
const validate = new Ajv2020({ allErrors: true, strict: false, validateFormats: false }).compile(schema);
const names = new Set();
for (const fixture of catalog.fixtures) {
  if (!fixture.name || !["inbound", "outbound"].includes(fixture.direction) || !("message" in fixture)) {
    throw new Error("ACP v2 fixture metadata is invalid");
  }
  if (!names.add(fixture.name)) throw new Error(`duplicate ACP v2 fixture: ${fixture.name}`);
  if (!validate(fixture.message)) {
    throw new Error(`ACP v2 fixture ${fixture.name} is invalid: ${JSON.stringify(validate.errors)}`);
  }
}
const requiredNames = [
  "initialize-request", "initialize-response", "auth-login-request", "auth-login-response",
  "auth-logout-request", "auth-logout-response", "session-new-request", "session-new-response",
  "session-list-request", "session-list-response", "session-resume-request", "session-resume-response",
  "session-close-request", "session-close-response", "session-delete-request", "session-delete-response",
  "session-prompt-request", "session-prompt-response", "session-cancel-notification",
  "running-update", "idle-update", "requires-action-update", "agent-message-chunk-update",
  "user-message-replay-update", "agent-message-replay-update", "usage-update", "tool-diff-update",
  "structured-error-response", "batch-request", "batch-response",
];
const missing = requiredNames.filter((name) => !names.has(name));
if (missing.length) throw new Error(`ACP v2 fixture coverage is incomplete: ${missing.join(", ")}`);
process.stdout.write(`ACP v2 fixtures valid: ${catalog.fixtures.length}\n`);
